import { forwardRef, useId, type KeyboardEvent } from 'react';
import { Send } from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { counterVisible, isSendable, MESSAGE_MAX_CHARS } from '@/lib/askAi';

export const DATA_USE_NOTE =
  "Answers are generated by an AI from this repository's code and graph and can be wrong. Your question and code excerpts are sent to Google Gemini or Groq on their free tiers, which may use them to improve their products.";

interface ComposerProps {
  value: string;
  onChange: (value: string) => void;
  onSend: () => void;
  /** Why sending is not possible right now, shown beside the field; null when it is. */
  disabledReason: string | null;
  sending: boolean;
}

/** Enter sends, Shift+Enter adds a line. The text stays whatever happens; the caller only clears it after a success. */
export const Composer = forwardRef<HTMLTextAreaElement, ComposerProps>(function Composer({ value, onChange, onSend, disabledReason, sending }, ref) {
  const id = useId();
  const noteId = `${id}-note`;
  const canSend = disabledReason === null && isSendable(value);
  const over = value.trim().length > MESSAGE_MAX_CHARS;

  const onKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
    if (event.key === 'Enter' && !event.shiftKey && !event.nativeEvent.isComposing) {
      event.preventDefault();
      if (canSend) onSend();
    }
  };

  return (
    <form
      className="grid gap-xs"
      onSubmit={(event) => {
        event.preventDefault();
        if (canSend) onSend();
      }}
    >
      <label htmlFor={id} className="field-label">Your question</label>
      <div className="flex flex-col gap-sm sm:flex-row sm:items-end">
        <textarea
          ref={ref}
          id={id}
          className="input min-h-[3rem] flex-1 resize-y"
          rows={2}
          value={value}
          disabled={disabledReason !== null}
          aria-describedby={noteId}
          aria-invalid={over || undefined}
          placeholder="Ask about this repository's code"
          onChange={(event) => onChange(event.target.value)}
          onKeyDown={onKeyDown}
        />
        <Button type="submit" variant="primary" loading={sending} disabled={!canSend} icon={<Send size={16} aria-hidden="true" />}>
          Ask
        </Button>
      </div>
      <div className="flex flex-wrap items-baseline justify-between gap-sm text-xs text-muted">
        <span id={noteId}>{disabledReason ?? 'Enter sends, Shift+Enter adds a line.'}</span>
        {counterVisible(value.length) ? (
          <span className={`num ${over ? 'text-error' : ''}`} aria-live="polite">
            {value.length} / {MESSAGE_MAX_CHARS}
          </span>
        ) : null}
      </div>
    </form>
  );
});
